import React, { useMemo } from "react";
import {
  Chart as ChartJS,
  CategoryScale,
  LinearScale,
  PointElement,
  LineElement,
  Tooltip,
  Legend,
} from "chart.js";
import { Line } from "react-chartjs-2";

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Tooltip, Legend);

export default function AnomalyChart({ anomalyScores, tamperedFrames, threshold }) {
  const tamperedSet = useMemo(() => new Set(tamperedFrames || []), [tamperedFrames]);

  const labels = useMemo(() => anomalyScores.map((_, i) => i), [anomalyScores]);
  const pointColors = useMemo(
    () => anomalyScores.map((_, i) => (tamperedSet.has(i) ? "rgba(220, 38, 38, 0.95)" : "rgba(59, 130, 246, 0.65)")),
    [anomalyScores, tamperedSet]
  );

  const data = useMemo(
    () => ({
      labels,
      datasets: [
        {
          label: "Anomaly score",
          data: anomalyScores,
          borderColor: "rgba(59, 130, 246, 0.9)",
          backgroundColor: "rgba(59, 130, 246, 0.2)",
          pointBackgroundColor: pointColors,
          pointRadius: 2,
          borderWidth: 1.5,
          tension: 0.2,
        },
        threshold != null
          ? {
              label: "Dynamic threshold",
              data: anomalyScores.map(() => threshold),
              borderColor: "rgba(234, 88, 12, 0.95)",
              pointRadius: 0,
              borderWidth: 2,
              borderDash: [6, 6],
              tension: 0,
            }
          : null,
      ].filter(Boolean),
    }),
    [labels, anomalyScores, pointColors]
  );

  const yMax = Math.max(
    1,
    ...(anomalyScores.length ? anomalyScores : [1]),
    threshold != null ? threshold : 1
  );

  const options = {
    responsive: true,
    maintainAspectRatio: false,
    plugins: {
      legend: { display: true, position: "top" },
      tooltip: { intersect: false, mode: "index" },
    },
    scales: {
      x: { title: { display: true, text: "Frame index" } },
      y: { title: { display: true, text: "Anomaly score" }, min: 0, max: yMax * 1.1 },
    },
  };

  return (
    <div style={{ height: 320 }}>
      <Line data={data} options={options} />
    </div>
  );
}
